<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { ChevronRight, Filter, Search, X } from 'lucide-vue-next'
import { useAppState } from '../../composables/useAppState'

const { courses, filters, query, showBuddyFilters, filteredStudents, buddyResultMessage, selectedProfile, go, toast, loadStudents, matchingSlots } = useAppState()

const pageSize = 10
const page = ref(1)
const pageCount = computed(() => Math.ceil(filteredStudents.value.length / pageSize))
const pagedStudents = computed(() => filteredStudents.value.slice((page.value - 1) * pageSize, page.value * pageSize))
// Changing a filter or the search starts again from the first page.
watch([filters, query], () => { page.value = 1 }, { deep: true })
watch(pageCount, count => { if (page.value > count) page.value = Math.max(1, count) })

// One pill per active filter, showing the part of this student that matched it.
// Course and goal are either/or, so only the one(s) this student matched get a pill.
function filterPills(student) {
    const pills = []
    const course = filters.value.course
    if (course && student.courseCodes.includes(course.toLowerCase()))
        pills.push(courses.value.find(item => item.startsWith(course + ' ')) || course)
    const goal = student.goals.find(item => item.toLowerCase() === filters.value.goal.toLowerCase())
    if (filters.value.goal && goal) pills.push(goal)
    if (filters.value.mode !== 'Any mode') pills.push(`Study mode: ${student.mode}`)
    if (filters.value.groupSize !== 'Any group size') pills.push(`Group size: ${student.groupSize}`)
    if (filters.value.availability !== 'Any availability') pills.push(...matchingSlots(student))
    return pills
}

// Reload on every visit so students who signed up since login appear.
onMounted(() => loadStudents().catch(error => toast(`Could not load students: ${error.message}`)))
</script>

