            <div class="priority-filters"><label class="field"><span>Course match <small>optional</small></span><select v-model="filters.course">
                        <option value="">Any course</option>
                        <option v-for="course in courses" :key="course" :value="course.split(' ')[0]">{{ course }}
                        </option>
                    </select></label><span class="or-label">OR</span><label class="field"><span>Study goal <small>optional</small></span><select v-model="filters.goal">
                        <option value="">Any goal</option>
                        <option>Concept review</option>
                        <option>Problem solving</option>
                        <option>Exam preparation</option>
                        <option>Project discussion</option>
                    </select></label></div>
            <div class="search-row">
                <div class="search-box">
                    <Search :size="18" /><input v-model="query" placeholder="Search student by name" />
                </div><button class="filter-button" @click="showBuddyFilters = !showBuddyFilters">
                    <Filter :size="16" /> Filters
                    <ChevronRight :class="{ rotate: showBuddyFilters }" :size="15" />
                </button>
            </div>
            <div v-if="!filteredStudents.length" class="no-results-message">{{ buddyResultMessage }}</div>
            <div v-if="selectedProfile" class="profile-preview-panel">
                <div class="match-title">
                    <h2>{{ selectedProfile.name }}</h2><button class="icon-button" @click="selectedProfile = null">
                        <X :size="16" />
                    </button>
                </div>
                <p>{{ selectedProfile.programme }}</p>
                <div class="preview-line"><span>Courses needing a
                        buddy</span><strong>{{ selectedProfile.course }}</strong></div>
                <div class="preview-line"><span>Study mode</span><strong>{{ selectedProfile.mode }}</strong></div>
                <div class="preview-line"><span>Weekly
                        availability</span><strong>{{ selectedProfile.availability }}</strong></div>
                <div class="preview-line"><span>Study goal</span><strong>{{ selectedProfile.goal }}</strong></div>
                <p class="private-contact">Contact number hidden until a connection is accepted.</p>
            </div>
            <div class="match-list">
                <article v-for="student in pagedStudents" :key="student.id" class="match-card">
                    <div style="margin-left: 1rem;" class="avatar avatar-lg" :class="`avatar-${student.color}`">{{ student.initials }}</div>
                    <div class="match-card-body">
                        <div class="match-title">
                            <h3>{{ student.name }}</h3><span class="score-pill">{{ student.score }}% match</span>
                        </div>
                        <p>{{ student.programme }}</p>
                        <div v-if="filterPills(student).length" class="match-details"><span
                                v-for="pill in filterPills(student)" :key="pill">{{ pill }}</span></div>
                        <div class="match-actions"><button class="secondary-button"
                                @click="selectedProfile = student; go('student/public-profile')">View public
                                profile</button>
                                <button style="margin-right:1rem;" class="primary-button" @click="toast(`Connection request sent to ${student.name}`)">Connect</button></div>
                    </div>
                </article>
            </div>
            <nav v-if="pageCount > 1" class="pagination" aria-label="Student results pages">
                <button class="secondary-button" :disabled="page === 1" @click="page--">Previous</button>
                <button v-for="number in pageCount" :key="number" class="page-number"
                    :class="{ active: number === page }" :aria-current="number === page ? 'page' : null"
                    @click="page = number">{{ number }}</button>
                <button class="secondary-button" :disabled="page === pageCount" @click="page++">Next</button>
